export const collectionTemplates={"silk-road-luxury-trains":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Train Journeys | SUKHA</title><meta name=\"description\" content=\"Explore Chengdu, Golden Panda Express, Jinxiu Tianfu and Baiyun rail journeys from the supplied 2027 brochures.\"><link rel=\"canonical\" href=\"https://sukha-travel-20261103.racinglight1.chatgpt.site/silk-road-luxury-trains/\"><meta property=\"og:title\" content=\"Silk Road Luxury Rail Journeys\"><meta property=\"og:description\" content=\"Explore Chengdu, Golden Panda Express, Jinxiu Tianfu and Baiyun rail journeys from the supplied 2027 brochures.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://sukha-travel-20261103.racinglight1.chatgpt.site/silk-road-luxury-trains/\"><meta property=\"og:image\" content=\"https://sukha-travel-20261103.racinglight1.chatgpt.site/assets/home-v1/beijing.webp\"><link rel=\"stylesheet\" href=\"/style.css\"><script src=\"/app.js\" defer></script><link rel=\"stylesheet\" href=\"/quote-builder.css\"><script src=\"/quote-builder.js\" defer></script><link rel=\"stylesheet\" href=\"/immersive-photos.css\"><link rel=\"stylesheet\" href=\"/travel-editorial.css\"><link rel=\"stylesheet\" href=\"/rail-collection.css\"><link rel=\"stylesheet\" href=\"/yangzi-explorer.css\"></head><body class=\"rail-collection travel-editorial\"><a class=\"skip\" href=\"#main\">Skip to content</a><header><a class=\"brand\" href=\"/\" aria-label=\"SUKHA home\"><span class=\"logo-crop\"><img src=\"/assets/logo.jpg\" alt=\"行界 SUKHA\"></span><span class=\"brand-note\">PRIVATE CHINA JOURNEYS</span></a><nav id=\"navigation\" aria-label=\"Main navigation\"><a href=\"/private-china-tours/\">Private Tours</a><a href=\"/silk-road-luxury-trains/\" aria-current=\"page\">Train Journeys</a><a href=\"/yangtze-river-cruises/\">River Cruises</a><a href=\"/our-story/\">About Us</a></nav><a class=\"button nav-cta\" href=\"/#request-quote\">Request a Quote<span aria-hidden=\"true\">↗</span></a><button id=\"menu-toggle\" aria-label=\"Open navigation\" aria-expanded=\"false\" aria-controls=\"navigation\">☰</button></header><main id=\"main\"><section class=\"page-intro wrap\"><p class=\"eyebrow\">TRAIN JOURNEYS</p><h1>China, at a<br><em>different pace.</em></h1><p class=\"lede\">Distinctive trains. Remarkable landscapes. Explore the 2027 rail collection, then shape the journey around you.</p></section><section class=\"wrap cruise-collection-list\" id=\"train-collection\" aria-label=\"Train collection\"><article class=\"cruise-collection-card\" id=\"chengdu\"><a class=\"cruise-collection-image\" href=\"/silk-road-luxury-trains/chengdu/\" aria-label=\"Explore Panda Train · Chengdu\"><img src=\"/assets/trains/chengdu-exterior.webp\" alt=\"Chengdu train following a railway curve in the supplied train handbook\" loading=\"lazy\"><span>Chengdu train · image extracted from the supplied train handbook, PDF page 2.</span></a><div class=\"cruise-collection-copy\"><p class=\"eyebrow\">熊猫专列·成都号</p><h2>Panda Train · Chengdu</h2><p class=\"cruise-duration\">16 days · 2027</p><p>Sichuan-inspired spaces, panda-themed hospitality and a 16-day journey across northern and southern Xinjiang.</p><p>Chengdu · Lanzhou · Turpan · Kashgar · Kuqa · Ili · Altay · Urumqi</p><a class=\"button\" href=\"/silk-road-luxury-trains/chengdu/\">Explore this train ↗</a></div></article><article class=\"cruise-collection-card\" id=\"jinxiu-dongfang\"><a class=\"cruise-collection-image\" href=\"/silk-road-luxury-trains/jinxiu-dongfang/\" aria-label=\"Explore Golden Panda Express\"><img src=\"/assets/trains/dongfang-kanas.webp\" alt=\"Kanas river scenery reproduced from the Jinxiu Dongfang itinerary PDF\" loading=\"lazy\"><span>Kanas route illustration · extracted from the Jinxiu Dongfang brochure, PDF page 6; not a train interior.</span></a><div class=\"cruise-collection-copy\"><p class=\"eyebrow\">锦绣东方号 · Jinxiu Dongfang</p><h2>Golden Panda Express</h2><p class=\"cruise-duration\">16 days · 2027</p><p>A 16-day Xinjiang collection with themed choices across Urumqi, Altay, Ili and Kuqa, and Kashgar.</p><p>Chengdu · Urumqi · Altay · Ili · Kuqa · Kashgar · Chengdu</p><a class=\"button\" href=\"/silk-road-luxury-trains/jinxiu-dongfang/\">Explore this train ↗</a></div></article><article class=\"cruise-collection-card\" id=\"jinxiu-tianfu\"><a class=\"cruise-collection-image\" href=\"/silk-road-luxury-trains/jinxiu-tianfu/\" aria-label=\"Explore Jinxiu Tianfu\"><img src=\"/assets/trains/tianfu-sayram.webp\" alt=\"Sayram Lake and distant snowy mountains reproduced from the Jinxiu Tianfu brochure\" loading=\"lazy\"><span>Sayram Lake route illustration · extracted from the Jinxiu Tianfu brochure, PDF page 9.</span></a><div class=\"cruise-collection-copy\"><p class=\"eyebrow\">熊猫专列·锦绣天府号</p><h2>Jinxiu Tianfu</h2><p class=\"cruise-duration\">16 days · 2027</p><p>Song-dynasty-inspired aesthetics and Sichuan brocade themes frame a 16-day Xinjiang journey, with a choice of cultural and landscape-led excursions.</p><p>Chengdu · Urumqi · Altay · Ili · Kuqa · Kashgar · Chengdu</p><a class=\"button\" href=\"/silk-road-luxury-trains/jinxiu-tianfu/\">Explore this train ↗</a></div></article><article class=\"cruise-collection-card\" id=\"baiyun\">\n  <a class=\"cruise-collection-image\" href=\"/silk-road-luxury-trains/baiyun/\" aria-label=\"Explore Baiyun\">\n    <img src=\"/assets/trains/baiyun-salon.webp\" alt=\"Promotional onboard cultural salon illustration reproduced from the Baiyun brochure\" loading=\"lazy\">\n    <span>Onboard cultural salon · promotional illustration extracted from the Baiyun brochure, PDF page 4; final configuration may differ.</span>\n  </a>\n  <div class=\"cruise-collection-copy\"><p class=\"eyebrow\">南方列车·白云号</p>\n    <h2>Baiyun</h2><p class=\"cruise-duration\">18 days · 2027</p>\n    <p>An 18-day journey from Guangzhou through Chongqing to the landscapes of Xinjiang, returning via Korla and Golmud.</p><p>Guangzhou · Chongqing · Urumqi · Altay · Ili · Kuqa · Kashgar · Korla · Golmud · Guangzhou</p><p>Price on request</p>\n    <a class=\"button\" href=\"/silk-road-luxury-trains/baiyun/\">Explore this train ↗</a>\n  </div>\n</article></section><section class=\"ivory\"><div class=\"wrap section\"><div class=\"section-head\"><div><p class=\"eyebrow\">THE EXPERIENCE, CONSIDERED</p><h2>What will shape your rail journey?</h2></div><p></p></div><div class=\"info-grid\"><article><span class=\"eyebrow\">01</span><h3>The train experience</h3><p>Compare the supplied train collection, routes and onboard spaces with your travel designer.</p></article><article><span class=\"eyebrow\">02</span><h3>Cabins & suites</h3><p>Review available brochure imagery, layouts, room sizes and facilities before choosing a cabin.</p></article><article><span class=\"eyebrow\">03</span><h3>Life on board</h3><p>Understand the dining arrangements, service languages and onboard activities for your departure.</p></article><article><span class=\"eyebrow\">04</span><h3>Off-train discoveries</h3><p>Discuss cultural visits and private extensions in places such as Dunhuang and Kashgar.</p></article></div></div></section><section class=\"wrap section\"><div class=\"section-head\"><div><p class=\"eyebrow\">BEFORE YOU CHOOSE</p><h2>Every detail deserves<br>a clear answer.</h2></div></div><div class=\"table-scroll\"><table><thead><tr><th>What to confirm</th><th>What your proposal should explain</th></tr></thead><tbody><tr><th>Departure & route</th><td>Actual departure city, dates, stops and the final operating itinerary.</td></tr><tr><th>Cabin & capacity</th><td>Confirmed cabin category, occupancy, facilities and available allocation.</td></tr><tr><th>Included services</th><td>Meals, excursions, transfers and any optional or additional charges.</td></tr><tr><th>Before travel</th><td>Luggage limits, accessibility, age conditions and any route-specific requirements.</td></tr><tr><th>Changes & cancellation</th><td>The operator’s applicable payment, change and cancellation conditions.</td></tr></tbody></table></div></section><section class=\"wrap section\"><div class=\"section-head\"><div><p class=\"eyebrow\">EXTEND THE STORY</p><h2>Beyond the railway.</h2></div><p></p></div><div class=\"journal-grid\"><a href=\"/signature-experiences/silk-road/\"><span>CULTURE & EXCHANGE</span><h3>The Silk Road</h3><p>Follow the stories behind an extraordinary cultural landscape.</p><b>Explore ↗</b></a><a href=\"/signature-experiences/xuanzang/\"><span>FAITH & DISCOVERY</span><h3>In the Footsteps of Xuanzang</h3><p>A cultural journey concept inspired by curiosity, knowledge and exchange.</p><b>Explore ↗</b></a><a href=\"/journeys/ancient-silk-road/\"><span>PRIVATE EXTENSIONS</span><h3>Make time for more.</h3><p>Explore a suggested private itinerary across western China.</p><b>Explore ↗</b></a></div></section><section class=\"final-cta\"><p class=\"eyebrow\">A JOURNEY THAT IS YOURS</p><h2>Your China story<br>starts here.</h2><p>Tell us what inspires you. Let’s shape the journey around you.</p><a class=\"button light\" href=\"/#request-quote\">Start Planning<span aria-hidden=\"true\">↗</span></a></section></main><footer><div class=\"footer-top\"><div><a class=\"wordmark\" href=\"/\">SUKHA<span>行界 · CHINA, BEYOND THE EXPECTED.</span></a><p>Private journeys. Remarkable experiences.<br>A deeper China.</p></div><div><h3>Explore China</h3><a href=\"/private-china-tours/\">Private journeys</a><a href=\"/silk-road-luxury-trains/\">Luxury rail</a><a href=\"/yangtze-river-cruises/\">Yangtze cruises</a></div><div><h3>Get to know us</h3><a href=\"/our-story/\">Our story</a><a href=\"/travel-journal/\">The China Journal</a><a href=\"/booking-information/\">How booking works</a></div><div><h3>Start a conversation</h3><a href=\"/#request-quote\">Request a quote ↗</a><a href=\"/privacy/\">Privacy & this preview</a><a href=\"mailto:devin@sukhatrip.com\">devin@sukhatrip.com</a><a href=\"tel:+8613908050651\">+86 139 0805 0651</a><a href=\"https://wa.me/8613908050651\" target=\"_blank\" rel=\"noopener noreferrer\">WhatsApp ↗</a><a href=\"https://work.weixin.qq.com/kfid/kfcacdbd3247535705c\" target=\"_blank\" rel=\"noopener noreferrer\">WeChat Customer Service ↗</a></div></div><div class=\"footer-bottom\"><span>© 2026 SUKHA · 行界</span><span>Private China journeys · Designed around you.</span></div></footer></body></html>","yangtze-river-cruises":"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Yangtze River Cruises | SUKHA</title><meta name=\"description\" content=\"Compare Yangzi Explorer, Yangtze Miracle, Yangtze Gold Cruises and Century Legend, then tailor your private China journey.\"><link rel=\"canonical\" href=\"https://sukha-travel-20261103.racinglight1.chatgpt.site/yangtze-river-cruises/\"><meta property=\"og:title\" content=\"Yangtze River Cruises\"><meta property=\"og:description\" content=\"Explore Yangzi Explorer 2027 voyages. Choose your route, departure and balcony suite, then tailor your China journey with SUKHA.\"><meta property=\"og:type\" content=\"website\"><meta property=\"og:url\" content=\"https://sukha-travel-20261103.racinglight1.chatgpt.site/yangtze-river-cruises/\"><meta property=\"og:image\" content=\"https://sukha-travel-20261103.racinglight1.chatgpt.site/assets/cruise-pdf-century-p10-0.jpg\"><link rel=\"stylesheet\" href=\"/style.css\"><script src=\"/app.js\" defer></script><link rel=\"stylesheet\" href=\"/yangzi-explorer.css\"><link rel=\"stylesheet\" href=\"/quote-builder.css\"><script src=\"/quote-builder.js\" defer></script><link rel=\"stylesheet\" href=\"/immersive-photos.css\"><link rel=\"stylesheet\" href=\"/travel-editorial.css\"></head><body><a class=\"skip\" href=\"#main\">Skip to content</a><header><a class=\"brand\" href=\"/\" aria-label=\"SUKHA home\"><span class=\"logo-crop\"><img src=\"/assets/logo.jpg\" alt=\"行界 SUKHA\"></span><span class=\"brand-note\">PRIVATE CHINA JOURNEYS</span></a><nav id=\"navigation\" aria-label=\"Main navigation\"><a href=\"/private-china-tours/\">Private Tours</a><a href=\"/silk-road-luxury-trains/\">Train Journeys</a><a href=\"/yangtze-river-cruises/\" aria-current=\"page\">River Cruises</a><a href=\"/our-story/\">About Us</a></nav><a class=\"button nav-cta\" href=\"/#request-quote\">Request a Quote<span aria-hidden=\"true\">↗</span></a><button id=\"menu-toggle\" aria-label=\"Open navigation\" aria-expanded=\"false\" aria-controls=\"navigation\">☰</button></header><main id=\"main\"><section class=\"page-intro wrap\"><p class=\"eyebrow\">THE SUKHA YANGTZE COLLECTION</p><h1>One river.<br><em>Find your way to travel.</em></h1><p class=\"lede\">From an intimate suite through the Three Gorges to a longer journey across China. Choose a cruise series to explore its voyages, cabins and possibilities.</p><div class=\"cruise-series-shortcuts\"><a href=\"#yangzi-explorer\">Yangzi Explorer ↓</a><a href=\"#yangtze-miracle\">Yangtze Miracle ↓</a><a href=\"#gold-cruises\">Yangtze Gold Cruises ↓</a><a href=\"#century-legend\">Century Legend ↓</a></div></section><section class=\"wrap cruise-collection-list\" aria-label=\"Cruise series\"><article class=\"cruise-collection-card\" id=\"yangzi-explorer\"><a class=\"cruise-collection-image\" href=\"/yangtze-river-cruises/yangzi-explorer/\" aria-label=\"Explore Yangzi Explorer\"><img src=\"/assets/cruise-pdf-explorer-p20-34.jpg\" alt=\"Three Gorges scenery from the Yangzi Explorer brochure\" loading=\"lazy\"><span>Supplied operator brochure image</span></a><div class=\"cruise-collection-copy\"><p class=\"eyebrow\">ALL-SUITE RIVER JOURNEYS</p><h2>Yangzi Explorer</h2><p class=\"cruise-duration\">3, 4 & 7 nights · 2027</p><p>An intimate all-suite voyage through the Three Gorges, with private balconies and a choice of cultural and nature experiences.</p><ul><li>74 balcony suites · up to 148 guests</li><li>Short voyages and seven-night round trips</li></ul><a class=\"button\" href=\"/yangtze-river-cruises/yangzi-explorer/\">Explore this series ↗</a></div></article><article class=\"cruise-collection-card\" id=\"yangtze-miracle\"><a class=\"cruise-collection-image\" href=\"/yangtze-river-cruises/yangtze-miracle/\" aria-label=\"Explore Yangtze Miracle\"><img src=\"/assets/cruise-pdf-miracle-p13-4.jpg\" alt=\"The open-air deck of Yangtze Miracle\" loading=\"lazy\"><span>Supplied operator brochure image</span></a><div class=\"cruise-collection-copy\"><p class=\"eyebrow\">FAMILIES, CULTURE & THE GORGES</p><h2>Yangtze Miracle</h2><p class=\"cruise-duration\">3 & 4 nights · 2027</p><p>Combine river scenery with shore experiences around Fuling and Wushan. Choose a themed family room, a river-view cabin or a suite.</p><ul><li>Chongqing–Yichang in either direction</li><li>Selected Shennongjia departures</li></ul><a class=\"button\" href=\"/yangtze-river-cruises/yangtze-miracle/\">Explore this series ↗</a></div></article><article class=\"cruise-collection-card\" id=\"gold-cruises\"><a class=\"cruise-collection-image\" href=\"/yangtze-river-cruises/gold-cruises/\" aria-label=\"Explore Yangtze Gold Cruises\"><img src=\"/assets/cruise-pdf-gold8-p08-1.jpg\" alt=\"The deck of Yangtze Gold 8\" loading=\"lazy\"><span>Supplied operator brochure image</span></a><div class=\"cruise-collection-copy\"><p class=\"eyebrow\">THE CLASSIC THREE GORGES</p><h2>Yangtze Gold Cruises</h2><p class=\"cruise-duration\">3 & 4 nights · 2027</p><p>A collection of ships for an easy-going river holiday, with balcony cabins, scheduled sightseeing and optional experiences ashore.</p><ul><li>Choose Gold 2, 3, 5, 6 or 8</li><li>Different ships, cabin layouts and services</li></ul><a class=\"button\" href=\"/yangtze-river-cruises/gold-cruises/\">Explore this series ↗</a></div></article><article class=\"cruise-collection-card\" id=\"century-legend\"><a class=\"cruise-collection-image\" href=\"/yangtze-river-cruises/century-legend/\" aria-label=\"Explore Century Legend\"><img src=\"/assets/cruise-pdf-century-p10-0.jpg\" alt=\"Century Legend sailing on the Yangtze\" loading=\"lazy\"><span>Supplied operator brochure image</span></a><div class=\"cruise-collection-copy\"><p class=\"eyebrow\">THE GRAND YANGTZE JOURNEY</p><h2>Century Legend</h2><p class=\"cruise-duration\">10 & 11 nights · 2026 reference programme</p><p>Follow the river between Chongqing and Shanghai on a longer journey through the gorges, cultural cities and the lower Yangtze.</p><ul><li>11-day downstream or 12-day upstream journey</li><li>Future departures and fares on request</li></ul><a class=\"button\" href=\"/yangtze-river-cruises/century-legend/\">Explore this series ↗</a></div></article></section><section class=\"wrap section narrow\"><p class=\"eyebrow\">NOT SURE WHERE TO START?</p><h2>We will help you choose.</h2><p>Tell us your dates, party size and travel style. We will compare suitable ships and connect your cruise with hotels, transfers and private touring.</p><a class=\"button\" href=\"/#request-quote\" data-quote-style=\"Yangtze cruise\">Help me plan my river journey ↗</a></section><section class=\"final-cta\"><p class=\"eyebrow\">A JOURNEY THAT IS YOURS</p><h2>Your China story<br>starts here.</h2><p>Tell us what inspires you. Let’s shape the journey around you.</p><a class=\"button light\" href=\"/#request-quote\">Start Planning<span aria-hidden=\"true\">↗</span></a></section></main><footer><div class=\"footer-top\"><div><a class=\"wordmark\" href=\"/\">SUKHA<span>行界 · CHINA, BEYOND THE EXPECTED.</span></a><p>Private journeys. Remarkable experiences.<br>A deeper China.</p></div><div><h3>Explore China</h3><a href=\"/private-china-tours/\">Private journeys</a><a href=\"/silk-road-luxury-trains/\">Luxury rail</a><a href=\"/yangtze-river-cruises/\">Yangtze cruises</a></div><div><h3>Get to know us</h3><a href=\"/our-story/\">Our story</a><a href=\"/travel-journal/\">The China Journal</a><a href=\"/booking-information/\">How booking works</a></div><div><h3>Start a conversation</h3><a href=\"/#request-quote\">Request a quote ↗</a><a href=\"/privacy/\">Privacy & this preview</a><a href=\"mailto:devin@sukhatrip.com\">devin@sukhatrip.com</a><a href=\"tel:+8613908050651\">+86 139 0805 0651</a><a href=\"https://wa.me/8613908050651\" target=\"_blank\" rel=\"noopener noreferrer\">WhatsApp ↗</a><a href=\"https://work.weixin.qq.com/kfid/kfcacdbd3247535705c\" target=\"_blank\" rel=\"noopener noreferrer\">WeChat Customer Service ↗</a></div></div><div class=\"footer-bottom\"><span>© 2026 SUKHA · 行界</span><span>Private China journeys · Designed around you.</span></div></footer></body></html>"};
